\label{thm2}


Any half-infinite Kronecker sequence $\mathbf{v}_0+j\mathbf{v}$, $j=0,1,2,3,\ldots,$ on a finite polysquare translation surface $\mathcal{P}$
is uniformly distributed.

\label{thm5}


Under the hypotheses of Theorem~\ref{thm4}, the following statements are equivalent:

\emph{(i)}
The $\mathbf{v}$-shift on $\mathcal{P}$ is ergodic.

\emph{(ii)}
For any $w\in\mathbb{R}$ such that $\mathbf{w}=(\mathbf{v},w)\in\mathbb{R}^3$ is the step vector of a Kronecker sequence on~$\mathcal{M}$,
the $\mathbf{w}$-shift in $\mathcal{M}$ is ergodic.

\label{thm7}


Under the hypotheses of Theorem~\ref{thm4}, the following statements are equivalent:

\emph{(i)}
Geodesic flow with direction $\mathbf{v}$ on $\mathcal{P}$ is ergodic.

\emph{(ii)}
For any $w\in\mathbb{R}$ such that $\mathbf{w}=(\mathbf{v},w)\in\mathbb{R}^3$ is a Kronecker direction,
geodesic flow with direction $\mathbf{w}$ in $\mathcal{M}$ is ergodic.

\label{lem31}


Suppose that the condition (i) in Theorem~\ref{thm4} holds.
Then the $\mathbf{v}$-shift $\mathbf{T}^*_\mathbf{v}=\mathbf{T}^*_\mathbf{v}(\mathcal{P})$ on $\mathcal{P}$ is ergodic.

\label{lem32}


Let $\mathcal{B}$ be a finite union of axis-parallel rectangular boxes satisfying \eqref{eq3.3}.
For every $\varepsilon_2>0$, there exists $\varepsilon_3>0$ and a finite set of disjoint
axis-parallel rectangular boxes such that their union $\mathcal{B}^*=\mathcal{B}^*(\mathcal{B};\varepsilon_2;\varepsilon_3)$ satisfies
the following conditions:

\emph{(i)}
The measure $\lambda_3(\mathcal{M}\setminus\mathcal{B}^*)<\varepsilon_2$.

\emph{(ii)}
We have $\chi_\mathcal{B}(\mathbf{s}')=\chi_\mathcal{B}(\mathbf{s}'')$ if the points $\mathbf{s}',\mathbf{s}''\in\mathcal{M}$ belong to the same axis-parallel
rectangular box in the disjoint union~$\mathcal{B}^*$.

\emph{(iii)}
The side lengths of each axis-parallel rectangular box in the disjoint union $\mathcal{B}^*$ is greater than~$\varepsilon_3$.

\emph{(iv)}
Let $s$ denote the number of atomic squares of~$\mathcal{P}$.
Then


\begin{displaymath}
\lambda_2\left(\left\{\mathbf{x}\in\mathcal{P}:\lambda_1(\{z\in[0,1):(\mathbf{x},z)\in\mathcal{B}^*\})>1-\varepsilon_2^{1/2}\right\}\right)>s-\varepsilon_2^{1/2}.
\end{displaymath}

\label{lem33}


The set of values $u_0\in[0,1)$ for which the inequalities


\begin{equation}\label{eq3.8}
\lambda_1(U_1\bigtriangleup(U_\sigma-u_0))\geqslant\frac{1}{32s^2}\lambda_1(U_1)(1-\lambda_1(U_1)),
\quad
\sigma=1,\ldots,s,
\end{equation}


hold simultaneously has Lebesgue measure at least~$1/2$.
